('Speechify','문서·웹·책을 자연스러운 음성으로 읽고 요약·질의하는 음성 AI #텍스트음성변환 #문서읽기 #AI요약 #접근성','Speechify는 웹페이지·PDF·문서·책을 음성으로 읽고 AI 요약·채팅·음성 입력을 제공하며 콘텐츠 제작용 Studio와 TTS API도 운영합니다.','https://speechify.com/','https://speechify.com/favicon.ico','Freemium','$0','Reader Free · Premium 월 $29 · Studio Starter 월 $19',array['Reader Free는 기본 음성과 최대 1.5배속을 제공합니다.','Reader Premium은 월 $29이며 자연스러운 음성·요약·채팅 기능을 제공합니다.','Studio Free는 600크레딧, Studio Starter는 월 $19이며 Reader와 별도 구독입니다.'],'USD','https://speechify.com/pricing/',now(),'Full Support',true,false,true,'https://docs.sws.speechify.com/','Native','specialized',array['텍스트 음성 읽기','AI 요약·질의','음성 콘텐츠 제작'],array['다국어 더빙','음성 복제','TTS API'],array['문서·웹을 이동 중 청취','한국어 포함 다국어 Studio','무료 API 시험 범위'],array['읽기 접근성이 필요한 사용자','문서와 책을 음성으로 소비하는 학습자'],array['Reader·Studio·API는 서로 다른 상품과 요금입니다.','Studio 무료 결과는 상업 이용 권리가 없습니다.','복제 음성에는 당사자 동의가 필요합니다.'],array['https://speechify.com/pricing/','https://speechify.com/pricing-studio/','https://speechify.com/pricing-api/'],now(),now()),
('Bolt.new','자연어로 풀스택 웹 앱을 만들고 데이터베이스·호스팅까지 연결하는 AI #앱제작 #코딩 #웹개발 #배포','Bolt.new는 브라우저에서 프롬프트로 웹 애플리케이션을 생성·수정하고 데이터베이스, 패키지, 도메인과 호스팅까지 연결하는 AI 앱 빌더입니다.','https://bolt.new/','https://bolt.new/favicon.ico','Freemium','$0','Free 월 100만 토큰 · Pro 월 $25',array['Free는 일 30만·월 100만 토큰과 호스팅을 제공합니다.','Pro는 월 $25부터 월 1,000만 토큰과 사용자 도메인·브랜딩 제거를 제공합니다.','Teams는 월 $30/인부터입니다.'],'USD','https://bolt.new/pricing',now(),'None',true,false,false,null,'Native','specialized',array['자연어 앱 제작','풀스택 코드 생성','웹 호스팅'],array['데이터베이스','사용자 도메인','AI 이미지 편집'],array['브라우저에서 앱 제작·배포','무료 데이터베이스·호스팅 진입점','생성 코드 직접 편집'],array['웹 MVP를 빠르게 만드는 창업자·개발자','프롬프트로 앱을 시험하는 비개발자'],array['프로젝트가 커질수록 파일 동기화 토큰 소비가 증가합니다.','무료 배포에는 Bolt 브랜딩이 표시됩니다.','생성 앱의 보안·권한·비용을 직접 검토해야 합니다.'],array['https://bolt.new/pricing','https://support.bolt.new/account-and-subscription/billing','https://support.bolt.new/faqs/account-and-subscription/tokens'],now(),now())
) as seed(name,description,full_description,url,logo_url,pricing_type,pricing_start_at,pricing_summary,pricing_details,pricing_currency,pricing_url,pricing_verified_at,korean_support_level,is_verified,is_domestic,has_api,api_url,ai_type,tool_scope,primary_features,secondary_features,key_benefits,best_for,limitations,verification_sources,verified_at,updated_at)
where not exists(select 1 from public.tools where lower(tools.url)=lower(seed.url));

with assignments(tool_url,category_slug) as (values
('https://agents.zapier.com/','productivity'),('https://agents.zapier.com/','business-marketing'),
('https://www.make.com/en/ai-agents','productivity'),('https://www.make.com/en/ai-agents','development'),
('https://n8n.io/','development'),('https://n8n.io/','productivity'),
('https://www.airtable.com/product/ai','productivity'),('https://www.airtable.com/product/ai','search-data'),
('https://v0.dev/','development'),('https://www.jetbrains.com/ai/','development'),
('https://julius.ai/','search-data'),('https://julius.ai/','productivity'),
('https://rows.com/ai','search-data'),('https://rows.com/ai','productivity'),
('https://hex.tech/','search-data'),('https://hex.tech/','development'),
('https://www.intercom.com/fin','business-marketing'),('https://www.intercom.com/fin','productivity'),
('https://www.microsoft.com/microsoft-365-copilot','productivity'),('https://www.microsoft.com/microsoft-365-copilot','business-marketing'),
('https://murf.ai/','video-audio'),('https://www.zendesk.com/service/ai/','business-marketing'),('https://www.zendesk.com/service/ai/','productivity'),
('https://speechify.com/','video-audio'),('https://speechify.com/','education'),
('https://bolt.new/','development')
)
insert into public.tool_categories(tool_id,category_id)
select tools.id,categories.id from assignments
join public.tools on lower(tools.url)=lower(assignments.tool_url)
join public.categories on lower(categories.slug)=lower(assignments.category_slug)
on conflict(tool_id,category_id) do nothing;
